/** The signed-in Server browser image's build context (signed-in/), file name to content. */
export const SIGNED_IN_FILES: Readonly<Record<string, string>> = {
  "Dockerfile": "# Signed-in Server browser image for the browser-prompt plugin: neko (https://github.com/m1k1o/neko,\n# Apache-2.0) with Chromium, a desktop the owner can watch and take over over WebRTC, plus the\n# plugin's overrides. Built locally by the plugin only after the owner's explicit choice in its\n# settings (the base image is about 1.5 GB) and tagged with a hash of this build context, never\n# `latest`. The base image is pinned by digest: neko 3.2.0 with Chromium 155.\n# Overrides:\n#   - chromium.conf: Chromium's own sandbox on, DevTools protocol on 127.0.0.1:9222 inside the\n#     container only (for the run agent's Playwright MCP, which shares this container's network\n#     namespace), session restore, no crash bubble; no --bwsi (guest mode would not keep logins).\n#   - chromium-start.sh: removes stale profile locks and starts Chromium with the filtering proxy\n#     sidecar as its only way out (also for loopback), refusing to start without it.\n#   - policies.json: neko's policy without the forced Google extensions, with DevTools allowed\n#     (needed for the protocol), cookies kept (neko ships session-only cookies), no password\n#     manager, autofill, sync, sign-in, downloads, file pickers, extensions, metrics reporting or\n#     background mode, standard Safe Browsing, and every internal page blocked (chrome://*,\n#     chrome-untrusted://*, chrome-search://*, chrome-extension://*, devtools://*, view-source:,\n#     about:*, javascript:, data:, file://) except about:blank and chrome://newtab (which opens about:blank), so neither\n#     the agent nor a page can read history, settings or the list of signed-in sites there.\n#   - viewer.css: neko's web client shows its on-screen keyboard button only below 769 px, so an\n#     iPad could tap but not type; this stylesheet (linked from neko's index.html) shows it on touch\n#     screens of any width.\nFROM ghcr.io/m1k1o/neko/chromium:3.2.0@sha256:270face8b8111e639744fb7bcdbbf0deed227900bb89d58b2f8adfc12af8c41e\n\nCOPY chromium.conf /etc/neko/supervisord/chromium.conf\nCOPY chromium-start.sh /usr/local/bin/chromium-start.sh\nCOPY policies.json /etc/chromium/policies/managed/policies.json\nRUN chmod 0755 /usr/local/bin/chromium-start.sh && chmod 0644 /etc/neko/supervisord/chromium.conf /etc/chromium/policies/managed/policies.json\nCOPY viewer.css /var/www/assets/bp-viewer.css\nRUN chmod 0644 /var/www/assets/bp-viewer.css \\\n  && sed -i 's#</head>#<link rel=\"stylesheet\" href=\"./assets/bp-viewer.css\"></head>#' /var/www/index.html \\\n  && grep -q 'href=\"./assets/bp-viewer.css\"' /var/www/index.html\n",
  "chromium-start.sh": "#!/bin/sh\n# Starts Chromium for the browser-prompt signed-in Server browser (see chromium.conf). Removes the\n# profile locks a previous container left (the container's host name changes on every start), and\n# sends every request through the filtering proxy sidecar (BP_PROXY), loopback included, so pages\n# can reach neither this container's own services (neko, the DevTools port) nor private, tailnet or\n# host addresses. Without a valid BP_PROXY it does not start Chromium at all.\n# Bitwarden (only in the image variant built after the owner's consent, see signed-in-bitwarden/):\n# when /opt/bitwarden holds the pinned extension, Chromium loads it from there (read-only, never\n# updated) and disables every other extension. Without it, Bitwarden's data is removed from the\n# profile (its vault cache, settings and storage), so turning Bitwarden off leaves nothing of it.\nPROFILE=/home/neko/.config/chromium\nBITWARDEN=/opt/bitwarden\nBITWARDEN_ID=nngceckbapebfimnlniiiahkandclblb\nrm -f \"$PROFILE/SingletonLock\" \"$PROFILE/SingletonCookie\" \"$PROFILE/SingletonSocket\"\nif ! printf '%s' \"${BP_PROXY:-}\" | grep -Eq '^http://(bp-si-[0-9a-f]{8}-proxy|[0-9]{1,3}(\\.[0-9]{1,3}){3}):[0-9]{1,5}$'; then\n  echo \"browser-prompt: BP_PROXY is missing or not http://<stack proxy or ipv4>:<port>; refusing to start Chromium without the proxy\" >&2\n  sleep 10\n  exit 1\nfi\nif [ -f \"$BITWARDEN/manifest.json\" ] && [ -f \"$BITWARDEN/browser-prompt-pin.json\" ]; then\n  exec /usr/bin/chromium \"$@\" --load-extension=\"$BITWARDEN\" --disable-extensions-except=\"$BITWARDEN\" --proxy-server=\"$BP_PROXY\" --proxy-bypass-list=\"<-loopback>\"\nfi\nfor dir in \"$PROFILE\"/Default \"$PROFILE\"/Profile*; do\n  [ -d \"$dir\" ] || continue\n  rm -rf \"$dir/Local Extension Settings/$BITWARDEN_ID\" \"$dir/Sync Extension Settings/$BITWARDEN_ID\" \"$dir/Managed Extension Settings/$BITWARDEN_ID\" \\\n    \"$dir/Storage/ext/$BITWARDEN_ID\" \"$dir/Extensions/$BITWARDEN_ID\" \"$dir/IndexedDB/chrome-extension_${BITWARDEN_ID}_0.indexeddb.leveldb\" \\\n    \"$dir/IndexedDB/chrome-extension_${BITWARDEN_ID}_0.indexeddb.blob\" \"$dir/File System/chrome-extension_${BITWARDEN_ID}_0\"\ndone\nexec /usr/bin/chromium \"$@\" --proxy-server=\"$BP_PROXY\" --proxy-bypass-list=\"<-loopback>\"\n",
  "chromium.conf": "[program:chromium]\nenvironment=HOME=\"/home/%(ENV_USER)s\",USER=\"%(ENV_USER)s\",DISPLAY=\"%(ENV_DISPLAY)s\"\ncommand=/usr/local/bin/chromium-start.sh\n  --disable-gpu-sandbox\n  --remote-debugging-port=9222\n  --remote-debugging-address=127.0.0.1\n  --window-position=0,0\n  --display=%(ENV_DISPLAY)s\n  --user-data-dir=/home/neko/.config/chromium\n  --no-first-run\n  --start-maximized\n  --disable-file-system\n  --disable-gpu\n  --disable-software-rasterizer\n  --disable-dev-shm-usage\n  --disable-session-crashed-bubble\n  --restore-last-session\n  --disable-quic\n  --no-pings\n  --disable-component-update\n  --disable-domain-reliability\n  --disable-breakpad\n  --disable-sync\n  --disable-features=WebUIOmniboxPopup,WebUIOmniboxFullPopup,WebUIOmniboxAimPopup\n  --force-webrtc-ip-handling-policy=disable_non_proxied_udp\n  --webrtc-ip-handling-policy=disable_non_proxied_udp\nstopsignal=INT\nstopwaitsecs=20\nautorestart=true\npriority=800\nuser=%(ENV_USER)s\nstdout_logfile=/var/log/neko/chromium.log\nstdout_logfile_maxbytes=10MB\nstdout_logfile_backups=1\nredirect_stderr=true\n\n[program:openbox]\nenvironment=HOME=\"/home/%(ENV_USER)s\",USER=\"%(ENV_USER)s\",DISPLAY=\"%(ENV_DISPLAY)s\"\ncommand=/usr/bin/openbox --config-file /etc/neko/openbox.xml\nautorestart=true\npriority=300\nuser=%(ENV_USER)s\nstdout_logfile=/var/log/neko/openbox.log\nstdout_logfile_maxbytes=10MB\nstdout_logfile_backups=1\nredirect_stderr=true\n",
  "policies.json": "{\n  \"AutofillAddressEnabled\": false,\n  \"AutofillCreditCardEnabled\": false,\n  \"BrowserSignin\": 0,\n  \"DefaultNotificationsSetting\": 2,\n  \"DeveloperToolsAvailability\": 1,\n  \"EditBookmarksEnabled\": false,\n  \"FullscreenAllowed\": true,\n  \"IncognitoModeAvailability\": 1,\n  \"SyncDisabled\": true,\n  \"AutoplayAllowed\": true,\n  \"BrowserAddPersonEnabled\": false,\n  \"BrowserGuestModeEnabled\": false,\n  \"DefaultPopupsSetting\": 2,\n  \"DownloadRestrictions\": 3,\n  \"AllowFileSelectionDialogs\": false,\n  \"PromptForDownloadLocation\": false,\n  \"BookmarkBarEnabled\": false,\n  \"PasswordManagerEnabled\": false,\n  \"BrowserLabsEnabled\": false,\n  \"CommandLineFlagSecurityWarningsEnabled\": false,\n  \"DefaultCookiesSetting\": 1,\n  \"MetricsReportingEnabled\": false,\n  \"SafeBrowsingProtectionLevel\": 1,\n  \"BackgroundModeEnabled\": false,\n  \"NewTabPageLocation\": \"about:blank\",\n  \"URLBlocklist\": [\n    \"file://*\",\n    \"chrome://*\",\n    \"chrome-untrusted://*\",\n    \"chrome-search://*\",\n    \"chrome-extension://*\",\n    \"devtools://*\",\n    \"view-source:*\",\n    \"about:*\",\n    \"javascript://*\",\n    \"javascript:*\",\n    \"data:*\"\n  ],\n  \"URLAllowlist\": [\n    \"about:blank\",\n    \"chrome://newtab\"\n  ],\n  \"ExtensionInstallBlocklist\": [\n    \"*\"\n  ]\n}\n",
  "viewer.css": "/* browser-prompt: neko's client shows its on-screen keyboard button (and the take-control button on\n   the video) only on screens up to 768 px wide (`phone:block hidden`), so on an iPad (834 px and\n   wider) the owner could tap but never type. Touch screens of any width get them too. neko renders\n   the keyboard button only on touch devices (no fine pointer, no hover), so this changes nothing\n   with a mouse or trackpad. */\n@media (pointer: coarse) and (min-width: 769px) {\n  .phone\\:block {\n    display: block;\n  }\n}\n",
};

/** The Bitwarden variant's build context (signed-in-bitwarden/), file name to content. */
export const SIGNED_IN_BITWARDEN_FILES: Readonly<Record<string, string>> = {
  "Dockerfile": "# Bitwarden variant of the browser-prompt signed-in Server browser image. Built by the plugin only\n# after the owner's explicit two-press consent in its settings (Signed-in Server browser ›\n# Bitwarden), on top of the plugin's own signed-in image (BASE_IMAGE, built from signed-in/), and\n# tagged with a hash of both build contexts, never `latest`.\n#   - install-bitwarden.py downloads the Bitwarden Password Manager release pinned in bitwarden.json\n#     from Bitwarden's GitHub releases, refuses it unless size and SHA-256 match, and puts it\n#     read-only in /opt/bitwarden. chromium-start.sh loads it from there (unpacked, so Chromium never\n#     updates it) and disables every other extension.\n#   - policy-overlay.json: Bitwarden is the only extension (types and install sources locked, no\n#     external extensions, the Chrome Web Store blocked); chrome-extension:// pages are no longer\n#     blocked by URL (Bitwarden's inline menu frames use per-session dynamic ids no allowlist entry\n#     can name; the agent is kept off them by the plugin's filters); Chromium's password manager\n#     and autofill stay off.\nARG BASE_IMAGE\nFROM ${BASE_IMAGE}\nCOPY bitwarden.json policy-overlay.json install-bitwarden.py /tmp/bp-bitwarden/\nRUN python3 -I /tmp/bp-bitwarden/install-bitwarden.py /tmp/bp-bitwarden && rm -rf /tmp/bp-bitwarden\n",
  "bitwarden.json": "{\n  \"version\": \"2026.11.0\",\n  \"url\": \"https://github.com/bitwarden/clients/releases/download/browser-v2026.11.0/bit-dist-chrome-2026.11.0.zip\",\n  \"sha256\": \"07cf19b8f79e649005fdeee67c85d3cf31c735449a01a37a5b9f0287732605a5\",\n  \"size\": 33808971,\n  \"id\": \"nngceckbapebfimnlniiiahkandclblb\",\n  \"key\": \"\",\n  \"lockShortcut\": \"Ctrl+Shift+7\"\n}\n",
  "install-bitwarden.py": "# Installs the pinned Bitwarden Password Manager extension into the browser-prompt signed-in image\n# (see Dockerfile). Runs once at image build time, only after the owner's explicit two-press consent\n# in the plugin's settings. Python's standard library only.\n#   1. Downloads the release zip named in bitwarden.json from Bitwarden's GitHub releases (https only)\n#      and refuses it unless its size and SHA-256 match the pin.\n#   2. Extracts it to /opt/bitwarden (regular files only, no absolute or .. paths), root-owned and\n#      read-only for the browser user, so Chromium (which loads it unpacked with\n#      --load-extension, see chromium-start.sh) can never update or change it.\n#   3. Checks the manifest (pinned version, Manifest V3, no update_url), adds the Chrome Web Store's\n#      public key for the extension so it gets its usual id, and gives Bitwarden's own \"Lock vault\"\n#      command a shortcut (the daemon presses it through the desktop when the owner releases control).\n#   4. Applies policy-overlay.json to Chromium's managed policy (remove, set, drop from lists, append).\nimport base64, hashlib, io, json, os, stat, sys, urllib.request, zipfile\n\nhere = sys.argv[1]\npin = json.load(open(os.path.join(here, \"bitwarden.json\")))\noverlay = json.load(open(os.path.join(here, \"policy-overlay.json\")))\ntarget = \"/opt/bitwarden\"\npolicy_file = \"/etc/chromium/policies/managed/policies.json\"\n\nprefix = \"https://github.com/bitwarden/clients/releases/download/browser-v%s/\" % pin[\"version\"]\nif not pin[\"url\"].startswith(prefix) or not pin[\"url\"].endswith(\".zip\"):\n    sys.exit(\"refusing: the pinned URL is not a Bitwarden browser release zip on GitHub\")\n\nclass HttpsOnly(urllib.request.HTTPRedirectHandler):\n    def redirect_request(self, req, fp, code, msg, headers, newurl):\n        if not newurl.startswith(\"https://\"):\n            raise urllib.error.URLError(\"refusing a redirect away from https\")\n        return super().redirect_request(req, fp, code, msg, headers, newurl)\n\nopener = urllib.request.build_opener(HttpsOnly)\nwith opener.open(urllib.request.Request(pin[\"url\"], headers={\"User-Agent\": \"browser-prompt-image-build\"}), timeout=300) as response:\n    data = response.read(pin[\"size\"] + 1)\nif len(data) != pin[\"size\"]:\n    sys.exit(\"refusing: the download is %d bytes, the pin says %d\" % (len(data), pin[\"size\"]))\ndigest = hashlib.sha256(data).hexdigest()\nif digest != pin[\"sha256\"]:\n    sys.exit(\"refusing: SHA-256 %s does not match the pin %s\" % (digest, pin[\"sha256\"]))\n\nos.makedirs(target, exist_ok=False)\nwith zipfile.ZipFile(io.BytesIO(data)) as archive:\n    for info in archive.infolist():\n        name = info.filename\n        if name.startswith(\"/\") or \"\\\\\" in name or \"..\" in name.split(\"/\"):\n            sys.exit(\"refusing: unsafe path in the archive: %r\" % name)\n        mode = (info.external_attr >> 16) & 0o170000\n        if mode and mode not in (stat.S_IFREG, stat.S_IFDIR):\n            sys.exit(\"refusing: not a regular file in the archive: %r\" % name)\n        path = os.path.join(target, name)\n        if name.endswith(\"/\"):\n            os.makedirs(path, exist_ok=True)\n            continue\n        os.makedirs(os.path.dirname(path), exist_ok=True)\n        with open(path, \"wb\") as out:\n            out.write(archive.read(info))\n\nmanifest_path = os.path.join(target, \"manifest.json\")\nmanifest = json.load(open(manifest_path, encoding=\"utf-8-sig\"))\nif manifest.get(\"version\") != pin[\"version\"] or manifest.get(\"manifest_version\") != 3:\n    sys.exit(\"refusing: unexpected manifest version\")\nif \"update_url\" in manifest:\n    sys.exit(\"refusing: the release zip carries an update_url\")\nkey = base64.b64decode(pin[\"key\"])\next_id = \"\".join(chr(97 + (b >> 4)) + chr(97 + (b & 15)) for b in hashlib.sha256(key).digest()[:16])\nif ext_id != pin[\"id\"]:\n    sys.exit(\"refusing: the pinned key does not give the pinned extension id\")\nmanifest[\"key\"] = pin[\"key\"]\ncommands = manifest.get(\"commands\") or {}\nif \"lock_vault\" not in commands:\n    sys.exit(\"refusing: this Bitwarden version has no lock_vault command\")\ncommands[\"lock_vault\"][\"suggested_key\"] = {\"default\": pin[\"lockShortcut\"], \"linux\": pin[\"lockShortcut\"]}\nused = [c for c in commands.values() if c.get(\"suggested_key\")]\nif len(used) > 4:\n    sys.exit(\"refusing: more than 4 suggested shortcuts\")\nfor name, command in commands.items():\n    if name != \"lock_vault\" and pin[\"lockShortcut\"] in (command.get(\"suggested_key\") or {}).values():\n        sys.exit(\"refusing: the lock shortcut is taken by %s\" % name)\nwith open(manifest_path, \"w\") as out:\n    json.dump(manifest, out, indent=2)\nwith open(os.path.join(target, \"browser-prompt-pin.json\"), \"w\") as out:\n    json.dump({\"version\": pin[\"version\"], \"sha256\": digest, \"id\": ext_id, \"url\": pin[\"url\"]}, out)\n\nfor root, dirs, files in os.walk(target):\n    os.chmod(root, 0o755)\n    for name in files:\n        os.chmod(os.path.join(root, name), 0o644)\n\npolicy = json.load(open(policy_file))\nfor name in overlay[\"remove\"]:\n    policy.pop(name, None)\npolicy.update(overlay[\"set\"])\n# Bitwarden's inline menu and notification frames use per-session dynamic ids\n# (chrome-extension://<random>/overlay/...), which no allowlist entry can name: extension pages are\n# no longer blocked by URL. Every other extension is disabled, and the agent's access to extension\n# pages is refused by the plugin's DevTools and MCP filters.\nfor name, values in overlay.get(\"drop\", {}).items():\n    policy[name] = [v for v in policy.get(name, []) if v not in values]\nfor name, values in overlay[\"append\"].items():\n    policy[name] = list(policy.get(name, [])) + [v for v in values if v not in policy.get(name, [])]\nwith open(policy_file, \"w\") as out:\n    json.dump(policy, out, indent=2)\nos.chmod(policy_file, 0o644)\nprint(\"installed Bitwarden %s (%s), sha256 %s\" % (pin[\"version\"], ext_id, digest))\n",
  "policy-overlay.json": "{\n  \"remove\": [\n    \"ExtensionInstallBlocklist\"\n  ],\n  \"set\": {\n    \"ExtensionInstallAllowlist\": [\n      \"nngceckbapebfimnlniiiahkandclblb\"\n    ],\n    \"ExtensionAllowedTypes\": [\n      \"extension\"\n    ],\n    \"ExtensionInstallSources\": [],\n    \"BlockExternalExtensions\": true,\n    \"PasswordManagerEnabled\": false,\n    \"AutofillAddressEnabled\": false,\n    \"AutofillCreditCardEnabled\": false\n  },\n  \"drop\": {\n    \"URLBlocklist\": [\n      \"chrome-extension://*\"\n    ]\n  },\n  \"append\": {\n    \"URLAllowlist\": [\n      \"chrome-extension://nngceckbapebfimnlniiiahkandclblb/*\"\n    ],\n    \"URLBlocklist\": [\n      \"chromewebstore.google.com\",\n      \"chrome.google.com/webstore\"\n    ]\n  }\n}\n",
};
